window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d05_prj49"]={"title": "Информационный отчет НМЗ_2025", "pages": 61, "pagesTxt": ["[стр. 1]\nДиректор Департамента реализации \r\nпроектов геологоразведочных работ\r\nООО «Норникель Технические \r\nСервисы» \r\n__________________ И.П. Иванов\r\n_____________________2025 г.\r\nИНФОРМАЦИОННЫЙ ОТЧЕТ\r\nо проведенных работах по мониторингу состояния геологической \r\nсреды на промышленной площадке и гидротехнических сооружениях \r\nхвостохранилища Надеждинского металлургического завода\r\nимени Б.И. Колесникова в 2025 г.\r\nНачальник отдела мониторинга и\r\nгидрогеологического сопровождения проектов\r\nООО «Норникель Технические Сервисы» В.А. Строганов\r\nГлавный гидрогеолог отдела мониторинга и\r\nгидрогеологического сопровождения проектов\r\nООО «Норникель Технические Сервисы» Д.С. Куприянов \r\nНорильск, 2025 г.", "[стр. 2]\n2\r\nСОДЕРЖАНИЕ\r\nВВЕДЕНИЕ ........................................................................................................ 4\r\n1.1 Географическое и административное положение.................................. 6\r\n1.2 Хвостохранилище НМЗ .......................................................................... 7\r\n1.3 Промышленная площадка НМЗ............................................................ 13\r\n2. ВИДЫ И ОБЪЕМЫ ВЫПОЛНЕННЫХ РАБОТ ............................................ 16\r\n3. МЕТОДИКА ПРОВЕДЕНИЯ И РЕЗУЛЬТАТЫ РАБОТ................................. 17\r\n3.1 Бурение наблюдательных гидрохимических скважин.......................... 17\r\n3.2 Опробование скважин гидрохимической сети ..................................... 17\r\n3.3 Растепление ледяных пробок в скважинах.......................................... 18\r\n3.4 Приведение в рабочее состояние действующих скважин .................... 18\r\n3.5. Обслуживание скважин КИА............................................................... 18\r\n3.6 Ликвидация скважин........................................................................... 19\r\n3.7 Камеральные работы .......................................................................... 20\r\n4. РЕЗУЛЬТАТЫ МОНИТОРИНГА НАБЛЮДЕНИЙ В РАЙОНЕ ОБЪЕКТОВ \r\nНМЗ ................................................................................................................. 21\r\n4.1 Мониторинг на хвостохранилище НМЗ ................................................ 21\r\n4.1.1 Результаты бурения скважин на хвостохранилища НМЗ ........... 21\r\n4.1.2. Результаты опробования скважин КИА на хвостохранилища НМЗ\r\n......................................................................................................... 22\r\n4.1.3. Результаты наблюдений за химическим составом подземных вод \r\nв скважинах гидрохимической сети хвостохранилища НМЗ............... 24\r\n4.1.4. Результаты растеплений ледяных пробок в скважинах и \r\nнаблюдений за уровнем подземных вод в скважинах режимной хх \r\nНМЗ в 2025 году................................................................................ 31\r\n4.1.5. Приведение в рабочее состояние скважин на хвостохранилища \r\nНМЗ................................................................................................... 35\r\n4.1.6. Обслуживание наружных элементов КИА............................... 35\r\n4.1.7. Ликвидационный тампонаж скважин КИА на хвостохранилище \r\nНМЗ................................................................................................... 35\r\n4.2 Мониторинг в пределах промышленной площадки НМЗ ...................... 36\r\n4.2.1 Результаты наблюдений за химическим составом подземных вод \r\nпромышленной площадки НМЗ.......................................................... 36\r\nЗАКЛЮЧЕНИЕ ................................................................................................ 40\r\nСПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ.............................................. 43", "[стр. 3]\n3\r\nСписок иллюстраций\r\nРис. 1.1. Обзорная схема участка работ .......................................................... 11\r\nРис. 1.2. Схема расположения скважин КИА пробуренных на хвостохранилище \r\nНМЗ в 2025 году .................................................................................. 12\r\nРис. 1.3 Схема расположения скважин КИА на промышленной площадке НМЗ в\r\n2025 году............................................................................................. 15\r\nРис. 1.4. Графики изменения химического состава воды из скважин \r\nгидрохимической сети хвостохранилища НМЗ за 2021-2025 \r\nгг. .............................................Ошибка! Закладка не определена.\r\nСписок таблиц в тексте\r\nТаблица 2.1 Виды и объемы работ, выполненных в 2025 году.......................... 16\r\nТаблица 4.1. Объемы бурения скважин на объектах НМЗ ................................. 21\r\nТаблица 4.2. Конструкция скважин, пробуренных в 2025 году.......................... 21\r\nТаблица 4.3. Результаты работ по откачке воды из скважин гидрохимической \r\nсети НМЗ в 2025 году........................................................................................ 23\r\nТаблица 4.4. Химический состав подземных вод скважин гидрохимической сети \r\nхвостохранилища НМЗ и промышленной площадки НМЗ в 2025 г..................... 25\r\nТаблица 4.5. Сравнительный химический состав подземных вод скважин \r\nгидрохимической сети хх НМЗ за 2021-2025 гг. ................................................ 26\r\nТаблица 4.6. Формула Курлова и название подземных вод скважин \r\nгидрохимической сети хх НМЗ за 2021-2025 гг. ................................................ 27\r\nТаблица 4.7. Результаты растеплений ледяных пробок и наблюдений за уровнем \r\nподземных вод в скважинах режимной сети хх НМЗ в 2025 году ...................... 31\r\nТаблица 4.8. Статические уровни в пьезометрических и гидрохимических \r\nскважинах х/х НМЗ за 2021-2025 гг. ................................................................. 34\r\nТаблица 4.9. Результаты Обслуживания скважин КИА на гидротехнических \r\nсооружениях хвостохранилища НМЗ в 2025 году .............................................. 35\r\nТаблица 4.10. Химический состав подземных вод на промышленной площадке \r\nНМЗ за 2021-2025 гг. ........................................................................................ 38\r\nТаблица 4.11. Формула Курлова и название подземных вод на промышленной \r\nплощадке НМЗ за 2021-2025 гг. ........................................................................ 38\r\nТаблица 4.12. Агрессивность подземных вод на промышленной площадке НМЗ \r\nза 2021-2025 гг................................................................................................. 39\r\nТекстовые Приложения\r\nПриложение 1................................................................................................... 44\r\nПриложение 2................................................................................................... 46", "[стр. 4]\n4\r\nВВЕДЕНИЕ\r\nРаботы по ведению Мониторинга геологической среды на \r\nгидротехнических сооружениях хвостохранилища Надеждинского \r\nметаллургического завода имени Б.И. Колесникова (НМЗ) проводились Отделом\r\nмониторинга и гидрогеологического сопровождения проектов ООО «НН \r\nТехнические Сервисы» в соответствии с договором №НН-ТС-ЗФ-2025/425 от \r\n21.03.2025 (далее - Договор).\r\nПолевые работы и работы с привлечением бурового и вспомогательного \r\nоборудования выполнялись подрядной организацией ООО НПО \r\n«Гидротехпроект», на основании договора № ННТС-409/2024 от 28.01.2025, \r\nинформационный отчет составлен специалистами ООО НПО «Гидротехпроект» в \r\nсоответствии договором и Техническим заданием.\r\nЛабораторные исследования выполнялись в Центре радиационно￾экологического контроля Контрольно-аналитического управления ЗФ ПАО «ГМК \r\n«Норильский никель» (Аттестат аккредитации на момент выполнения анализов \r\n№RA.RU.21HH29 от 13 сентября 2016г.). Аттестат аккредитации в Приложении 1. \r\nВ настоящем информационном отчете представлены результаты работ, \r\nпроведенных на хвостохранилище Надеждинского металлургического завода\r\nимени Б.И. Колесникова (далее - НМЗ) и производственной площадке, \r\nпримыкающей к грануляционному бассейну плавильного цеха № 1 НМЗ согласно \r\n«Программе мониторинга подземных вод в зоне эксплуатации подземного \r\nсооружения Надеждинского металлургического завода имени Б.И. Колесникова\r\nЗаполярного филиала ПАО «ГМК Норильский Никель» [1] (далее - Программа \r\nмониторинга).\r\nЦелевым назначением мониторинга, учитывая расположение участка недр \r\nв зоне распространения многолетнемерзлых пород (ММП), является контроль за \r\nвозможным изменением мерзлотно-гидрогеологических условий на территории \r\nобъекта наблюдений. \r\nВ 2025 году выполнены работы:\r\n- бурение 1 наблюдательной КИА (120 п.м.) на промплощадке НМЗ, \r\n- бурение 3 наблюдательных КИА (90 п.м.) на хвостохранилище НМЗ;\r\n- опробование 1 гидронаблюдательной скважины гидрохимической сети на \r\nпроизводственной площадке НМЗ (плавильный цех №1);\r\n- опробование 7 скважин гидрохимической сети на хвостохранилище НМЗ (при \r\nдвукратном опробовании в год, итого -14 опробований);\r\n- растепление ледяных и конденсатных пробок в 53 скважинах КИА х/х НМЗ;\r\n- растепление ледяных и конденсатных пробок 6 скважин в потерне русловой \r\nплотины х/х НМЗ;\r\n- ликвидация 3 скважин на хвостохранилище НМЗ;\r\n- ликвидация 35 скважин в потерне русловой плотины хвостохранилища НМЗ;\r\n- Приведение в рабочее состояние действующих скважин на хвостохранилище \r\nНМЗ – 2 скв.;\r\n- Обслуживание наружных элементов КИА: термометрических, пьезометрических, \r\nгидронаблюдательных скважин и поверхностных марок (Сварка опознавательных \r\nфлажков, нанесение марок) – 17 скв.;\r\n- Камеральные работы – 2790 чел./час.", "[стр. 5]\n5\r\nРезультаты сведены в таблицы, построены сравнительные графики.\r\nТекущее состояние объектов МГС проведено аналитически по информационным \r\nработам за 5-летний период.\r\nКлючевые слова: мониторинг, хвостохранилище НМЗ, производственная \r\nплощадка, примыкающая к грануляционному бассейну плавильного цеха № 1, \r\nуровень грунтовых вод (УГВ), точка замера (т.з.), статический уровень, \r\nдинамический уровень, подземные воды, макрокомпоненты, микрокомпоненты, \r\nхимический состав подземных вод, природный фон, поверхностные воды, \r\nводоносный горизонт (ВГ), сезонно-талый слой (СТС), подземные воды \r\n(надмерзлотные воды, межмерзлотные воды, подмерзлотные воды), \r\nмакрокомпоненты, микрокомпоненты, химический состав подземных вод, \r\nприродный фон, химическое потребление кислорода (ХПК), биологическое \r\nпотребление кислорода (БПК), бутилксантогенат калия (Кх), натрия \r\nдибутилдитиофосфат (БАФ), гидротехническое сооружение (ГТС), контрольно￾измерительная аппаратура (КИА).", "[стр. 6]\n6\r\n1. ОБЩИЕ СВЕДЕНИЯ ОБ УЧАСТКЕ РАБОТ\r\n1.1 Географическое и административное положение\r\nОбъект мониторинга расположен на территории полуострова Таймыр\r\nв северной части Красноярского края в границах Норильского промышленного \r\nрайона, ограниченного географическими координатами 6830'-6930' с.ш. и \r\n8730'-8830' в.д. (листы топоосновы масштаба 1:50 000 R-45-92-В, Г; -93-А, Б; -\r\n93-В, Г; -104-А, Б; -105-А, Б). Норильский промышленный район административно \r\nвходит в состав Муниципального образования город Норильск (Рис 1.1).\r\nОсновным населенным пунктом НПР является Муниципальное образование \r\nг. Норильск (176,3 тыс. жителей), находящийся в 90 км к востоку от г. Дудинка и \r\nсвязанный с ним железной и шоссейной дорогами. В 25 км северо-восточнее \r\nЦентрального района г. Норильска расположен район Талнах, связанный с \r\nЦентральным районом шоссейной, а также одноколейной железной дорогами. В \r\n27 км западнее Центрального района г. Норильска находится район Кайеркан, \r\nсообщение с которым также осуществляется по железной и шоссейной дорогам. \r\nВ 8 км на северо-восток от Центрального района расположено жилое \r\nобразование Оганер, также входящее в состав г. Норильска. \r\nМинерально-сырьевой комплекс Заполярного филиала ПАО «ГМК \r\n«Норильский никель» представлен предприятиями добывающими и \r\nперерабатывающими медно-никелевые руды. Рудная база комбината состоит из \r\nместорождений богатых, медистых и вкрапленных медно-никелевых руд.\r\nМесторождение медно-никелевых руд Норильск-1 отрабатывается \r\nподземным рудником «Заполярный» и рудником открытых работ «Медвежий \r\nручей». На Талнахском и Октябрьском месторождениях, входящих в состав \r\nТалнахского рудного узла, отрабатываются богатые и медистые руды. \r\nМесторождения отрабатываются подземными рудниками «Маяк», \r\n«Комсомольский», «Октябрьский» и «Таймырский», «Скалистый».\r\nОбогащение руд осуществляется на Норильской и Талнахской \r\nобогатительных фабриках с получением медного, никелевого, пирротиновых \r\nконцентратов и отвальных хвостов. Концентраты направляются на \r\nметаллургические заводы, а хвосты складируются в хвостохранилище \r\n«Лебяжье». \r\nТопливно-энергетический комплекс НПР включает в себя газовую и \r\nэнергетическую промышленность. Добыча природного газа осуществляется АО \r\n«Норильскгазпром» на Мессояхском, Соленинском и Пеляткинского\r\nгазоконденсатных месторождениях, расположенных в 300 км западнее г. \r\nНорильска. Подача газа осуществляется по 4 ниткам газопроводов. \r\nЭнергетическая база Норильского промышленного района представлена тремя \r\nТЭЦ мощностью 500-600 тыс. кВт каждая: ТЭЦ-1 (г. Норильск), ТЭЦ-2 (г. Талнах) \r\nи ТЭЦ-3 (промплощадка Надеждинского металлургического завода), \r\nработающими на природном газе, а также Усть-Хантайской ГЭС, мощностью 450 \r\nтыс. кВт, расположенной в 150 км южнее г. Норильска, рядом с поселком \r\nСнежногорск и связанной с г. Норильском высоковольтной ЛЭП.\r\nСвязь с центральными районами России осуществляется авиатранспортом \r\nчерез аэропорт «Алыкель», расположенный между городами Норильск и \r\nДудинка. Доставка грузов производится через порт Дудинка по Северному \r\nморскому пути круглогодично, а в летний период и по реке Енисей.", "[стр. 7]\n7\r\nХозяйственно-питьевое водоснабжение городов осуществляется за счет \r\nподземных вод Ергалахского, Талнахского и Амбарнинского месторождений, на \r\nкоторых обустроены и эксплуатируются водозаборы подземных вод, а также за \r\nсчет двух водозаборов поверхностных вод р. Норильской.\r\n1.2 Хвостохранилище НМЗ\r\nЗавод располагается на плато Надежда на площадке бывшего аэропорта в \r\n12 км от г. Норильска на высоте 200–220 м над уровнем моря. В состав НМЗ \r\nвходят три производства – гидрометаллургическое (ГМП), пирометаллургическое \r\n(ПМП) и производство кислорода. Гидрометаллургическое производство от \r\nначала до конца технологической цепочки обогащения концентрата процесс \r\nпроисходит в водных растворах, в герметичных сосудах. Пирометаллургическое \r\nпроизводство перерабатывает никелевый и медный концентраты Талнахской \r\nобогатительной фабрики, сульфидный концентрат гидрометаллургического \r\nпроизводства. Пирометаллургический передел НМЗ – это анодный, обжиговый, \r\nконвертерный, электропечной участки, две линии взвешенной плавки, печь \r\nжидкой ванны, около двухсот километров внутренних трубопроводов. Готовой \r\nпродукцией завода являются: файнштейн, аноды медные, элементарная сера и \r\nтехнологический кислород. Медно-никелевый файнштейн и анодная медь -\r\nявляются высококонцентрированными по меди, никелю и кобальту \r\nполуфабрикатами, и перерабатываются до готовой продукции на смежных \r\nпеределах и предприятиях ГМК. \r\nХвостохранилище НМЗ ЗФ ПАО «ГМК «Норильский никель» находится в \r\nверховьях реки Буровой (Рис. 1.2), входящей в водосборный бассейн р. Дудинка, \r\nкоторая отведена с помощью системы отвода (гидрозащиты), на западе и севере \r\nграничит с бассейнами рек Амбарная и Далдыкан, которые входят в водосборную \r\nсистему оз. Пясино. Створ ограждающей дамбы расположен на водоразделе р. \r\nБуровая и р. Амбарная. Створ русловой плотины расположен в 5,2 км ниже истока \r\nр. Буровая.\r\nХвостохранилище – овражно-балочного типа, по способу заполнения —\r\nналивное, предназначено для складирования и хранения хвостов \r\nгидрометаллургического производства НМЗ (отходов от переработки \r\nпирротинового концентрата), поступающих в накопитель жидких промышленных \r\nотходов по системе гидротранспорта в виде пульпы, и осветления жидкой фазы \r\nпульпы, которая используется для оборотного водоснабжения завода.\r\nВ ноябре 1979 года было введено временное локальное хвостохранилище. \r\nВ октябре 1981 г. — введено в эксплуатацию основное хвостохранилище (I -я \r\nочередь). В ноябре 1981 г. начато строительство хвостового хозяйства, \r\nвходящего в состав II пускового комплекса расширения гидрометаллургического \r\nпередела НМЗ. В декабре 1989 г. рабочей комиссией принято в эксплуатацию \r\nпредъявленные к приемке — сбросной пульповод от НМЗ до хвостохранилища; \r\nрусловая плотина II очереди с полиэтиленовым экраном до отм. 290,00 м с ж/б \r\nпотерной и замораживающим комплексом на правом берегу; ограждающая дамба \r\nдо отм. 292,00 м с замораживающим комплексом; противофильтрационная завеса \r\nна левобережных каналах.\r\nС 2012 по 2016 гг. включительно ЗФ ОАО «ГМК «Норильский никель» в \r\nрамках проектных решений «НМЗ. ЦОСК. Реконструкция хвостохранилища с \r\nувеличением полезной емкости до 40 млн. м3» производилась отсыпка Русловой \r\nплотины и Ограждающей дамбы до отметок 296,0 м. абс., в следствии которой", "[стр. 8]\n8\r\nнаблюдательная сеть скважин КИА на этих гидротехнических объектах была \r\nполностью утеряна и восстановлена в 2016-2017 гг. в соответствии с тем же \r\nпроектом НМЗ-РХ-40.\r\nНапорный фронт на ограждающих гидротехнических сооружениях (ГТС) \r\nхвостохранилища НМЗ образуют: \r\n- русловая плотина хвостохранилища, общей протяженностью 1013,70 м;\r\n- ограждающая дамба, общей протяженностью 1100 м.\r\nСистема по отводу р. Буровой и перехвату поверхностного стока \r\nпредставлена:\r\n- водоподъемной дамбой №1 (каменно-набросная, талая); \r\n- водоподъемной дамбой №2 (каменно-набросная, талая);\r\n- четырьмя водоотводными каналами (левобережный канал № 1 с \r\nбыстротоком, левобережные каналы № 2 и № 3, правобережный канал с \r\nбыстротоком).\r\nРусловая плотина насыпная, каменно-земляная с полиэтиленовым \r\nэкраном. Упорная призма отсыпана из скального грунта с переходными слоями \r\nиз несортированного щебенистого грунта, гравий по песчаной смеси, песка. \r\nПлотина возведена на сложном таломерзлом основании, включающая в себя \r\nглубокий талик. Грунты основания Русловой плотины по составу и мерзлотным \r\nсвойствам условно разделены на три части: «правобережные», в надпойменной \r\nчасти ледниковые отложения представлены суглинками, супесями с включением \r\nгальки, гравия и валунов; «центральная» часть представлена эффузивным \r\nкомплексом пород, осложненных дизъюнктивными нарушениями;\r\n«левобережные» участок основания плотины представлен трещиноватыми \r\nкоренными породами, перекрытыми маломощным слоем (до 3 м) элювиально￾делювиальных отложений.\r\nОграждающая дамба насыпная, ядро и зуб отсыпаны из суглинка, \r\nпереходный слой из гравийно-галечникового грунта, низовой и верховой откосы \r\nотсыпаны из скального грунта. Ниже основания дамбы залегают \r\nмноголетнемерзлые ледниковые отложения мощностью от 10 до 50 метров.\r\nВодосборная площадь хвостохранилища в створе русловой плотины р. \r\nБуровой составляет 16,3 км2\r\n. Поверхностный сток отводится по периметру \r\nхвостохранилища водоотводными каналами, уменьшающими водосборную \r\nплощадь хвостохранилища до 4,5 км2\r\n. Отвод поверхностных вод и р. Буровой от \r\nакватории хвостохранилища осуществляется системой каналов и водоподъемных \r\nдамб. Основная часть поверхностного стока отводится в нижний бьеф русловой \r\nплотины в русло р. Буровой. Сброс излишней воды из хвостохранилища проектом \r\nне предусмотрен. Осуществляется только забор воды для оборотного \r\nводоснабжения плавучей насосной станцией первого подъема.\r\nМноголетнемёрзлые грунты занимают большую часть территории \r\nхвостохранилища. Криогенная текстура многолетнемёрзлых грунтов в пределах \r\nплощадки в основном массивная с льдистостью до 10÷15%. Исключение \r\nсоставляют верхние горизонты грунтовой толщи на глубину 3÷6 м, где имеют \r\nместо слоистая и сетчатая текстуры с общей льдистостью до 40%. При \r\nоттаивании эти слои переходят в текучепластичное и текучее состояние и \r\nхарактеризуются весьма низкими физико-механическими показателями. \r\nЗначительные скопления льда в виде прослоев и линз имеются в слое \r\nсезонного промерзания и приурочены, главным образом, к основаниям полочных \r\nсклонов и днищ местных понижений. Широкое развитие на склонах имеет \r\n«сухая» мерзлота. Она связана с плотными суглинками. В зоне выветривания", "[стр. 9]\n9\r\nбазальтов лёд совместно с грунтом является заполнителем трещин. В мёрзлом \r\nсостоянии они являются водонепроницаемыми. \r\nНа изучаемой территории выделяются следующие водоносные слои￾горизонты в той или иной мере связанные между собой:\r\nАллювиальные отложения мощностью 3-6 м с коэффициентом фильтрации \r\nот 0,1 до 100 м/сут. Расчетный коэффициент 50 м/сут.\r\nЛедниковые отложения мощностью от 2-5 м до 15-35 м с коэффициентом \r\nфильтрации от 0,01 до 30 м/сут. Расчетный коэффициент-10 м/сут.\r\nКоренные породы:\r\n- верхняя часть зоны поверхностного разуплотнения представлена сильно \r\nразрушенными породами. Мощность их меняется от 0,5 до 6 м, коэффициентом \r\nфильтрации от 10 м/сут до 200 м/сут.\r\n- нижняя часть зоны поверхностного разуплотнения представляет собой \r\nслабовыветрелые базальты с затрудненной циркуляцией подземных вод, \r\nмощность зоны составляет 20-25 м с коэффициентом фильтрации от 0,01 м/сут \r\nдо 50 м/сут. Расчетный коэффициент для трещиноватых разновидностей 50 \r\nм/сут, для слаботрещиноватых- 3 м/сут.\r\n- зона относительно сохранных слаботрещиноватых пород является \r\nпрактически водоупором с коэффициентом фильтрации от 0,01 м/сут до 1,0м/сут. \r\nРасчетный коэффициент- 0,05 м/сут.\r\n- зоны тектонических нарушений имеют линейную фильтрационную \r\nпроницаемость, ограниченную мощностью зон 1,0-10,0 м. В таких зонах в верхней \r\nчасти коэффициентом фильтрации до 10000 м/сут, с глубиной \r\nводопроницаемость резко падает.\r\nОбщая мощность многолетнемёрзлых пород составляет 120÷180 м, а \r\nнаиболее глубокий талик развит под руслом р. Буровой.\r\nНормативную мощность сезонного оттаивания по результатам расчетов в \r\nпределах распространения многолетнемерзлых крупнообломочных грунтов 3,5 м, \r\nглинистых грунтов принять равной 2 м. Нормативную мощность сезонного \r\nпромерзания в пределах распространения талых грунтов для крупнообломочных \r\nгрунтов 4 м, для глинистых грунтов 2,5 м.\r\nТаликовые зоны приурочены к пойменно-русловым участкам р. Буровой и \r\nруч. Безымянный. В створах водоподъемных дамб ширина таликовых зон \r\nсоставляет 50-150 метров, а в ложе хвостохранилища 150-200 метров. В пределах \r\nРусловой плотины до начала эксплуатации хвостохранилища талик имел ширину \r\n180 метров. Кроме этого в районе хвостохранилища отмечается развитие \r\nсклоновых надмерзлотных таликов небольших по площади и глубине (до 5-7 м), \r\nсформированных из-за интенсивной снегозаносимости (до 4 м и более) и \r\nзатрудненного оттока поверхностных вод.\r\nВ результате строительства и эксплуатации хвостохранилища НМЗ, \r\nтемпературный режим грунтов в ложе (чаше) техногенного объекта изменился. \r\nВ результате круглогодично сбрасываемой пульпы, сказывалось\r\nотепляющее воздействие на грунты тела и основания Русловой плотины, \r\nразвились техногенные талики. Ранее по результатам инженерно-геологических \r\nизысканий (проведенных до 2005 г.), был зафиксирован подрусловой талик р. \r\nБуровой (река до строительства проходила в центральной части плотины). После \r\nокончания реконструкции в 2017 г. в результате повышения уровня воды в пруде \r\nотстойнике снизилась ширина пляжной зоны, по температурным скважинам в \r\nпотерне было зафиксировано расширение талика в створе Русловой плотины по \r\nее основанию, температура грунтов повысились от минус 6,2-0,9оС до +1,0 -", "[стр. 10]\n10\r\n+2,0оС на подошве слоя нулевых годовых колебаний как четвертичных, так и в \r\nкоренных породах различной степени проницаемости и трещиноватости.\r\nПодземные воды на площади хвостохранилища представлены \r\nнадмерзлотными водами сезонноталого слоя, подмерзлотными водами и водами, \r\nлокализующимися в таликовых зонах.\r\nНадмерзлотные воды сезонно-талого слоя функционируют в летне￾осенний период и распространены повсеместно. Водоотводные каналы \r\nдренируют водоносный горизонт сезонно-талого слоя, расположенный выше по \r\nрельефу.\r\nПодмерзлотные воды вскрыты в 1 км ниже по рельефу от Русловой \r\nплотины на глубине 101 м, водовмещающими породами служат базальты со \r\nслабой степенью трещиноватости. В подрусловом талике р. Буровой подземные \r\nводы функционируют круглогодично.\r\nДлительная эксплуатация хвостохранилища привела к существенному \r\nизменению таликовых зон, в настоящее время образовавшиеся техногенные \r\nталики слились с подрусловыми. Воды, связанные с таликовой зоной р. Буровой\r\nв районе Русловой плотины, гидравлически могут быть связаны с \r\nподмерзлотными.\r\nГидродинамическая схема на площадке хвостохранилища представляет \r\nследующее: поток подземных вод выше хвостохранилища локализован в узкой \r\nзоне подруслового талика шириной 50 м, расход потока зависит от сезонных \r\nколебаний, далее на участке «хвостохранилище – Русловая плотина» имеет место \r\nсубвертикальный приток вод хвостохранилища в водоносный комплекс \r\nподруслового талика (ширина которого на данном участке составляет около 200 \r\nм), и который затруднен ввиду наличия отложений хвостов из мелкодисперсной \r\nфракции (в пляжной зоне), ниже Русловой плотины водоносный комплекс \r\nразгружается в русло р. Буровой в виде источников в нижнем бьефе, суммарный \r\nрасход которых фиксируется на участке от низового откоса плотины до станции \r\nоборотной воды.\r\nНа Ограждающей дамбе в 3-х створах установлена КИА состоящая из: 6 \r\nтермометрических, 6 пьезометрических скважин и 3 геодезических марок на \r\nгребне дамбы, всего КИА - 15.\r\nНа Русловой плотине в 4-х створах установлена КИА состоящая из: 8 \r\nтермометрических, 8 пьезометрических и 4 геодезических марки, всего КИА - 20. \r\nВ рамках инженерно-геологических изысканий 2020 года выполненных АО \r\n«Красноярская буровая компания» по периметру хвостохранилища НМЗ, в 12 \r\nстворах пробурены 29 скважин, по окончанию работ, переведены под режимные \r\nнаблюдения. \r\nВ 2025 году пробурено 3 пьезометрических скважины на русловой плотине \r\n(Рис. 1.2).", "[стр. 11]\n11\r\nРис. 1.1. Обзорная схема участка работ", "[стр. 12]\n12\r\nРис. 1.2. Схема расположения скважин КИА пробуренных на хвостохранилище \r\nНМЗ в 2025 г.", "[стр. 13]\n13\r\n1.3 Промышленная площадка НМЗ\r\nНадеждинский металлургический завод имени Б.И. Колесникова является \r\nструктурным подразделением и составной частью обогатительно￾металлургического производства Заполярного филиала Публичного \r\nакционерного общества «Горно-металлургическая компания «Норильский \r\nникель» (ЗФ ПАО «ГМК «Норильский никель»).\r\nНМЗ производит из рудного сырья, промпродуктов других структурных \r\nподразделений ЗФ ПАО «ГМК «Норильский никель»:\r\n- медно-никелевый файнштейн (сплав сульфидов никеля, меди, кобальта \r\nи железа);\r\n- медь анодную (не производится с 2016 года);\r\n- серу техническую. \r\nОсновная промышленная площадка НМЗ расположена в 6 км западнее г. \r\nНорильск на северном склоне Норильского плато на южной окраине скального \r\nвыступа. Абсолютные отметки рельефа изменяются в пределах 218,2 до 224,0 м. \r\nОбщий уклон рельефа наблюдается в северном направлении. Большая часть \r\nплощади (преимущественно западная половина) в пределах промплощадки НМЗ \r\nснивелирована и покрыта искусственным покрытием, вследствие чего \r\nестественный почвенный покров практически отсутствует, присутствуют только \r\nтехногенные почвенные образования.\r\nПромышленная площадка НМЗ относится к зоне развития сплошных по \r\nплощади многолетнемерзлых пород (ММП), с ежегодными циклами промерзания \r\n– протаивания, интенсивность которых находится в прямой зависимости от \r\nклиматических условий, литологического состава, положения в рельефе.\r\nПодземных воды в районе промплощадки классифицируются по их \r\nпространственному взаимоотношению с толщей ММП. В пределах района \r\nвыделяются надмерзлотные воды, воды сквозных таликов и подмерзлотные \r\nводы.\r\nПодземные воды получают питание преимущественно за счет \r\nповерхностных вод, а в летне-осенний период также за счет инфильтрации \r\nатмосферных осадков и вод сезонно-талого слоя, с которыми осуществляется \r\nгидравлическая связь. В замкнутых подозерных таликах подземные воды \r\nхарактеризуются застойным режимом. В подрусловых таликах фильтрационные \r\nпотоки направлены по уклону русла, разгрузка вод осуществляется в сквозные \r\nталики при впадении рек и ручьев в более крупные водоемы и водотоки.\r\nХимический состав вод надмерзлотных таликов во многом определяется \r\nсоставом поверхностных вод и вод сезонно-талого слоя. Эти воды относятся к \r\nгидрокарбонатному кальциевому, магниевому или натриевому типам. Воды \r\nпресные, их минерализация составляет 0,1-1 г/дм3\r\n.\r\nПо характеру распространения и развития подземные воды на территории \r\nработ на исследуемой глубине до 10,0 м надмерзлотные, порово-пластовые, \r\nбезнапорные в слое сезонного оттаивания. \r\nГрунтовые воды в породах слоя сезонного оттаивания имеют \r\nспорадическое распространение, низкую обильность и сезонное существование. \r\nС началом зимнего промерзания сфера циркуляции надмерзлотных вод \r\nсокращается, в декабре - январе они перемерзают. Водовмещающими породами \r\nсезонно-талого слоя являются крупнообломочные отложения. Нижним \r\nводоупором является кровля многолетнемёрзлых грунтов. Мощность водоносного", "[стр. 14]\n14\r\nгоризонта изменяется от 0,1 м до 1,5 м. Питание водоносного горизонта \r\nпроисходит за счёт атмосферных осадков, протаивания деятельного слоя, \r\nфильтрационного подпора поверхностных вод в паводковый период. Разгрузка \r\nпроисходит в местную эрозионную сеть. В ходе оттаивания деятельного слоя \r\nожидается повсеместное появление надмерзлотных вод. \r\nВода по макрокомпонентному составу гидрокарбонатная натриевая, весьма \r\nпресная, очень мягкая (жёсткость карбонатная).\r\nДля изучения локального нарушения режима подземных вод и \r\nтемпературного поля горного массива на территории промплощадки НМЗ, \r\nприлегающей непосредственно к действующему подземному объекту \r\n(грануляционный бассейн плавильного цеха №1, с колодцем) создана \r\nспециализированная наблюдательная сеть, состоящая из 10-ти \r\nпьезометрических скважин (Рис. 1.3).\r\nДанные наблюдательные скважины (пьезометры) на участке подземного \r\nсооружения позволяют контролировать состояние подземных вод \r\nнепосредственно под сооружением и по периметру.", "[стр. 15]\n15\r\nРис. 1.3 Схема расположения скважин КИА на промышленной площадке НМЗ, 2025 г.", "[стр. 16]\n16\r\n2. ВИДЫ И ОБЪЕМЫ ВЫПОЛНЕННЫХ РАБОТ\r\nВиды и объемы выполненных работ сведены в таблице 2.1.\r\nТаблица 2.1 Виды и объемы работ, выполненных в 2025 году", "[стр. 17]\n17\r\n3. МЕТОДИКА ПРОВЕДЕНИЯ И РЕЗУЛЬТАТЫ РАБОТ\r\n3.1 Бурение наблюдательных гидрохимических скважин\r\nБурение с поверхности осуществлялось буровой установкой УРБ-2А2, с \r\nполным отбором керна, Проходка скважин как в четвертичных отложениях, так \r\nи по коренным породам, велась с промывкой чистой технической водой.\r\nНа пробуренных скважинах КИА проводились наблюдения за уровнем \r\nгрунтовых вод (УГВ).\r\nДиаметр бурения скважин 151-76 мм, определялся с учетом необходимости \r\nспуска промежуточных обсадных колонн и основного конструктива. \r\nВ термометрических скважинах в интервале бурения выполнена (ОЗЦ) \r\nцементация затрубного пространства. В пьезометрических скважинах ОЗЦ \r\nвыполнена в приустьевой части до глубины 3,0 м. \r\nДля наблюдений все скважины оборудовались соответствующим \r\nконструктивом, термометрические – «глухой» трубой диаметром 76/56 мм на всю \r\nглубину, пьезометр - фильтром диаметром 89/76 мм в интервале талых пород или \r\nв трещиноватой части коренных пород. Дела скважин переданы заказчику (НМЗ). \r\nПьезометрические и термометрические скважины промаркированы \r\nустановлены в 4-х створах Русловой плотины, в 3-х створах Ограждающей дамбы, \r\nи других ГТС хвостохранилища НМЗ (на гребне и низовом откосе).\r\nВ маркировке КИА первая цифра в названии – это номер створа, буква\r\nуказывает на принадлежность скважины по назначению, далее цифровое \r\nобозначение по высоте низового откоса, от нижнего бьефа, где перед \r\nпорядковым № пишется цифра \"0\" и далее 1...2 по нарастанию высоты дамбы.\r\n3.2 Опробование скважин гидрохимической сети\r\nСостав работ, количество и местоположение скважин, предназначенных к \r\nопробованию, определяется Заказчиком в предписании, выдаваемом Подрядчику \r\nперед производством работ.\r\nПри проведении ОФР (откачка) предусматривается отбор проб воды из \r\nскважин на химический анализ. Предусматривается в конце каждой откачки, а \r\nтакже возможно после прокачки, перед проведением опыта по наливу или \r\nжелонированием. \r\nОпробование скважин проводится с применением грузопассажирского \r\nавтомобиля вездеходного класса с комплектом армированных шлангов, насосов, \r\nмобильной электростанции и компрессора. \r\nПеред проведением опробования выполняются работы по растеплению \r\nледяной пробки и чистке ствола скважины (при необходимости).\r\nДалее проводится прокачка/откачка с замерами уровней подземных вод до \r\nи после прокачки и определением дебита. Продолжительность прокачки \r\nрассчитывается по объёму извлекаемой воды: для незамерзающих скважин - 3 \r\nскважинных объёма, для скважин в мерзлоте – 4. Тип и характеристика \r\nводоподъемного оборудования, применяемого на каждой скважине \r\nсогласовывается с Заказчиком.", "[стр. 18]\n18\r\n3.3 Растепление ледяных пробок в скважинах\r\nВид работ выполняется для определения статического уровня подземных \r\nвод (после растепления льда в стволе пьезометрической скважины). Кроме этого \r\nвыполняется растепления ледяных (конденсатных) пробок, образующихся в \r\nтермометрической скважине (в приустьевой части ствола скважины, при на \r\nперепаде температур) для последующего производства работ по определению \r\nтемпературного состояния грунтов. \r\nРаботы по растеплению ледяных пробок, с последующим наблюдением за \r\nуровнем воды в скважинах КИА выполнены в 2025 году согласно перечню, \r\nпредоставленному Заказчиком.\r\nПеречень действий по чистке стволов скважин КИА от ледяных пробок:\r\n замер уровня ледяной пробки;\r\n наезд на скважину буровой установки;\r\n проведение спускоподъемных операций бурового инструмента;\r\n разбуривание ледяных пробок с применением породоразрушающего \r\nинструмента;\r\n продувка скважины компрессором, с целью прочистки ствола скважин \r\nот ледяных включений и воды;\r\n замер статического уровня воды после восстановления уровня.\r\n3.4 Приведение в рабочее состояние действующих скважин\r\nСостав работ, количество, тип и местоположение скважин, \r\nпредназначенных к ремонту/чистке, а также возможность проведения \r\nремонта/восстановления путем бурения скважин глубиной до 5-7 п.м. \r\n(поверхностная марка), определяется Заказчиком в предписании, выдаваемом \r\nПодрядчику перед производством работ. \r\nРемонтно-восстановительные работы ведутся с использованием буровой \r\nустановки, обеспечивающей фактические параметры для проработки ствола \r\nразличных типов скважин:\r\nпьезометрическая – max глубина – 100,0 м, max Ø – 112 мм;\r\nтермометрическая – max глубина – 50,0 м, max Ø – 96 мм;\r\nКонкретный состав работ по каждой скважине определяется исходя из \r\nхарактеристик, которые делают данную скважину непригодной для режимных \r\nнаблюдений.\r\nРемонтно-восстановительные работы могут включать в себя \r\nвосстановление конструктива скважин (пьезометрических, термометрических, \r\nобсадных труб, фильтров), устьевой обвязки (бетонная подушка, оголовок, \r\nрепер).\r\nПри проведении чистки скважины её ствол прорабатывается от устья до \r\nзабоя от илистых отложений и посторонних предметов с помощью \r\nпородоразрушающего инструмента, с выносом шлама на поверхность или \r\nжелонированием. \r\nЗатем производится прокачка скважины при помощи эрлифтной установки. \r\nПрокачка выполняется до полного осветления выходящей струи воды.\r\n3.5. Обслуживание скважин КИА", "[стр. 19]\n19\r\nСостав работ, количество, тип и местоположение скважин, \r\nпредназначенных к обслуживанию КИА, определяется Заказчиком в \r\nпредписании, выдаваемом Подрядчику перед производством работ. \r\nРемонтно-восстановительные работы ведутся оборудованием, \r\nобеспечивающим рабочее техническое состояние различных типов скважин \r\n(сварка реперов, опознавательных флажков, наголовников, покраска КИА).\r\nКонкретный состав работ по каждой скважине определяется исходя из \r\nвизуального состояния на устье КИА. В соответствии планом работ на 2025 год \r\nподрядной организацией ООО «Гидротехпроект» на хвостохранилище НМЗ \r\nпроведены работы по Обслуживанию скважин КИА, согласно объема работ,\r\nпредоставленного Заказчиком.\r\n3.6 Ликвидация скважин\r\nСостав работ, количество, тип и местоположение скважин, \r\nпредназначенных к ликвидации, определяется Заказчиком в предписании, \r\nвыдаваемом Подрядчику перед производством работ.\r\nЛиквидация скважин ведется станком, обеспечивающим фактические \r\nпараметры для проработки ствола различных типов скважин:\r\nГруппа скважин 1:\r\n- Средняя глубина ликвидируемой скважины составляет 60,0 м.\r\n- Диаметр скважины – 630-800 мм.\r\n- Диаметр конструктива, спущенного в скважину – 76мм.\r\nПринципиальная схема скважин приведена в Приложениях 3-6.\r\nГруппа скважин 2:\r\n- Средняя глубина ликвидируемой скважины составляет 30,0 м.\r\n- Диаметр скважины – 108-146 мм.\r\n- Диаметр конструктива, спущенного в скважину – 76мм.\r\nБуровой станок применяемый для ликвидации скважин в потерне х/х НМЗ \r\nсоответствует фактическим физическим характеристикам (ширина/высота) \r\nпотерны.\r\nПеред проведением ликвидации пьезометрической или термометрической \r\nскважины производится комплекс работ по её растеплению (при необходимости) \r\n– с помощью подачи теплой воды через шланги, на верхнюю кромку \r\nсформированной ледяной пробки или разбуриванием с помощью \r\nпородоразрушающего инструмента диаметром меньше, чем находящийся в \r\nскважине конструктив.\r\nВ случае технической возможности, металлический конструктив \r\nнаходящийся в скважине (пьезометрические, термометрические, обсадные \r\nтрубы) извлекается и утилизируется.\r\nПроизводится чистка/проработка ствола скважины от устья до забоя от \r\nилистых отложений и посторонних предметов с помощью породоразрушающего \r\nинструмента, с выносом шлама на поверхность или желонированием.\r\nДалее проводится ликвидационное тампонирование скважин цементным \r\nраствором с водоцементным отношением 0,5. \r\nВ процессе проведения тампонирования отбираются пробы цементного \r\nраствора. Время ожидания схватывания цемента должно быть не менее 24 часов.", "[стр. 20]\n20\r\nДля более быстрого схватывания цемента в его раствор добавляют \r\nускорители схватывания (хлористый натрий или хлористый кальций до 2% к весу \r\nсухого цемента, или жидкое стекло – 1%). \r\nЦементный раствор приготавливают в гидравлических цементомешалках, \r\nхорошо промытых и очищенных глиномешалках и растворомешалках, закачивают \r\nего цементировочными агрегатами или типовыми насосами буровой установки.\r\nУстьевая часть ликвидированной скважины цементируется вровень с \r\nповерхностью земли (полубочка) с углублением на 0,1 метров или при большом \r\nдиаметре непосредственно в обсадной колонне (обрезка превышения обсада по \r\nсогласованию с Заказчиком), с репером общей высотой не менее 2,5 м, с \r\nномером.\r\nПри ликвидации скважин в потерне русловой плотины х/х НМЗ допускается \r\nликвидация с цементацией на уровне забоя потерны (бетона), репер допускается \r\nне устанавливать, обозначение ликвидированной скважины указывать на борту \r\nпотерны (обезличенные скважины - по № секции в потерне).\r\n3.7 Камеральные работы\r\nВ течении года данные получаемые при проведении различных видов \r\nгидрогеологических работ оформляются в виде дел скважин и актов \r\nвыполненных работ. Итоговой отчетностью по проведенным работам является \r\nежегодный информационный отчет за по объектам МГС.\r\nИнформационные отчеты включают в себя обобщенные данные по \r\nпроведенным работам и сопровождается картографической, табличной и \r\nграфической информацией.\r\nВ состав камеральных работ данного отчета вошел анализ и \r\nсистематизация полученных полевых материалов: анализ данных по результатам \r\nзамеров уровней в пьезометрических и наблюдательных скважинах; анализ и \r\nсистематизация полученных данных по результатам проведенных откачек и \r\nхимических анализов отобранных проб, составление данного информационного \r\nотчета.", "[стр. 21]\n21\r\n4. РЕЗУЛЬТАТЫ МОНИТОРИНГА НАБЛЮДЕНИЙ В РАЙОНЕ ОБЪЕКТОВ \r\nНМЗ\r\n4.1 Мониторинг на хвостохранилище НМЗ\r\n4.1.1 Результаты бурения скважин на хвостохранилища НМЗ\r\nВ 2025 году на производственной площадке Надеждинского \r\nметаллургического завода имени Б.И. Колесникова пробурено 1 гидрохимическая\r\nскважина (ПР-11) глубиной 120 п.м.\r\nНа хвостохранилище НМЗ пробурено 3 пьезометрических скважины 3П-1, \r\n4П-1 и 4П-2, общий объем бурения составил – 90 п.м. (бурение 60 п.м. перенесено \r\nв потерну Русловой плотины хх НМЗ).\r\nВ потерне русловой плотины хвостохранилища НМЗ пробурено 6\r\nтермометрических скважин. Общий объем бурения составил – 180 п.м. \r\nВ таблице 4.1. представлены объемы бурения, местоположение, \r\nкоординаты и назначение пробуренных в 2025 году скважин КИА.\r\nВ таблице 4.2. представлены данные по конструкциям пробуренных в 2025 \r\nгоду скважин КИА.\r\nТаблица 4.1. Объемы бурения скважин на объектах НМЗ в 2025 году\r\nТаблица 4.2. Конструкция скважин КИА, пробуренных в 2025 году", "[стр. 22]\n22\r\n4.1.2. Результаты опробования скважин КИА на хвостохранилища НМЗ\r\nДля определения влияния производственного цикла Надеждинского \r\nметаллургического завода имени Б.И. Колесникова на состав подземных вод в \r\n2025 году были опробованы скважины гидрохимической сети: \r\n- 1 скважина на территории производственной площадки плавильного цеха \r\nНМЗ, \r\n- 3 скважины (дважды в год) в нижнем бьефе русловой плотины \r\nхвостохранилища НМЗ,\r\n- 2 скважины (дважды в год) в районе водоподъемной дамбы №1, \r\n- 2 скважины (дважды год) в районе водоподъемной дамбы №2.\r\nВ состав работ входил комплекс подготовительных работ: разбуривание \r\n(растепление) ледяных пробок в скважинах, откачка воды из скважин эрлифтной \r\nустановкой, отбор проб воды на химический анализ, наблюдения за уровнем \r\nподземных вод (статический и динамический). \r\nЛабораторные исследования выполнялись в Центре радиационно￾экологического контроля Контрольно-аналитического управления ЗФ ПАО «ГМК \r\n«Норильский никель» (Аттестат аккредитации на момент выполнения анализов \r\n№RA.RU.21HH29 от 13 сентября 2016 г.). Аттестат аккредитации представлен в \r\nПриложении 1. \r\nРезультаты работ по откачке воды из гидрохимических скважин в 2025 году \r\nпредставлены в таблице 4.3.\r\nПротоколы химического анализа подземных вод из гидрохимических \r\nскважин хвостохранилища и промплощадки НМЗ в 2025 г. приведены в \r\nПриложении 2.", "[стр. 23]\n23\r\nТаблица 4.3. Результаты работ по откачке воды из скважин гидрохимической сети НМЗ в 2025 году", "[стр. 24]\n24\r\n4.1.3. Результаты наблюдений за химическим составом подземных вод в \r\nскважинах гидрохимической сети хвостохранилища НМЗ\r\nВ соответствии с утвержденным планом работ в отчетном году проведено \r\n14 опробований в скважинах режимной сети. Опробование выполнялось дважды \r\nв год (в весенний и осенний период) в 3-х наблюдательных скважинах 2П-01 (ПХ￾8), 2П-02 (НХ-2), 2П-03, расположенных в нижнем бьефе Русловой плотины, для \r\nопределения степени влияния техногенного объекта на окружающую среду и \r\nвыявления возможного загрязнения подземных вод ниже по потоку от \r\nгидротехнического сооружения.\r\nДля оценки достоверности фоновой гидрохимической информации и \r\nгидрогеологической обстановки, в 2025 году дважды (в весенний и осенний \r\nпериоды) опробование выполнено, в 2-х скважинах 5П-1 (ПХ-5), 5П-02, \r\nрасположенных в районе на водоподъемной дамбе №2 и руч. Безымянный, и 2-\r\nскважинах 4П-1 (ПХ-4), 4П-01, расположенных в районе водоподъемной дамбе \r\n№1 и р. Буровая.\r\nРезультаты сокращенного химического состава подземных вод из скважин \r\nнаблюдательной сети хвостохранилища НМЗ за 2025 год приведены в таблице \r\n4.1., а также сравнительный анализ за пятилетний период [2-5] в таблице 4.2.\r\nФормулы Курлова и названия подземных вод из скважин наблюдательной \r\nсети хвостохранилища НМЗ за 2025 год, а также за пятилетний период [2-5] \r\nприведены в таблице 4.3.\r\nГрафики изменения химического состава по скважинам 2П-01 (ПХ-8), 2П￾02 (НХ-2), 2П-03 за 2021-2025 гг. приведены на рисунке 4.1.\r\nРезультаты наблюдений в гидрохимических скважинах: \r\n- 2П-01 (ПХ-8), техническое состояние скважины - удовлетворительное. \r\nСкважина расположена в нижнем бьефе русловой плотины. Водоносный горизонт \r\nвскрыт на границе четвертичных отложений и коренных пород, вскрыт в \r\nинтервале 10,0 – 20,0 м, уровень установился на глубине 6,8 м. В 2025 году \r\nводный режим остается стабильным относительно прошлого года, уровень в \r\nскважине оставался на глубине 7,0 м.\r\nВ 2025 году тип подземных вод по сравнению с прошлым годом не \r\nизменился, воды сульфатные кальциево-магниевые, минерализация находилась \r\nв пределах 7,38 – 6,93 г/дм3\r\n, воды соленые. Основным анионом является \r\nсульфаты (94-93%), в катионном составе превалирует магний (49-61%), в \r\nменьших содержаниях кальций (38-26%) и натрий. Превышения по предельно \r\nдопустимым концентрациям (ПДК) наблюдаются по компонентам: Ca, Mg, Feобщ, \r\nNa, SO4, - в 1 и 2 цикле опробования, а также по PO4\r\n3- в 1 цикле опробования.\r\nСпецкомпоненты не превышают пределы погрешности. Величина водородного \r\nпоказателя варьирует на уровне прошлого года, водная среда слабокислая (pH\r\nот 6,0 до 6,6).", "[стр. 25]\n25\r\nТаблица 4.4. Химический состав подземных вод скважин гидрохимической сети хвостохранилища НМЗ и промышленной \r\nплощадки НМЗ в 2025 г.\r\n.", "[стр. 26]\n26\r\nТаблица 4.5. Сравнительный химический состав подземных вод скважин гидрохимической сети хх НМЗ за 2020-2025 гг.", "[стр. 27]\n27\r\nТаблица 4.6. Формула Курлова и название подземных вод скважин гидрохимической сети хх НМЗ за 2020-2025 гг.", "[стр. 28]\n28\r\nРис. 1.4. Графики изменения химического состава воды из скважин гидрохимической сети хвостохранилища НМЗ за 2020-2025 гг.", "[стр. 29]\n29\r\nПродолжение Рис. 1.4.", "[стр. 30]\n30\r\n- 2П-02 (НХ-2), техническое состояние скважины - удовлетворительное. \r\nСкважина расположена в 1,5 км на юг от русловой плотины. Водоносный горизонт \r\nвскрыт на границе четвертичных отложений и коренных пород, вскрыт в \r\nинтервале 8,0 – 16,0 м, уровень воды в скважине установился на глубине 0,9 м. \r\nУровень подземных вод относительно стабилен, снижается в весенний период и \r\nповышается в послепаводковый период за счет активной инфильтрации осадков. \r\nВ химическом составе основным анионом являются сульфаты (80-67%), в \r\nменьшей степени гидрокарбонаты (13-31%), основные катионы кальций (64-\r\n59%) и магний (31-32%). Тип воды сульфатные магниево-кальциевые в 1 цикле \r\nопробования изменяются во 2 цикле на гидрокарбонатно-сульфатные магниево￾кальциевые, минерализация по году в пределах 2,14 г/дм3 – 0,572 г/дм3\r\n, воды от \r\nсолоноватых до пресных. По водородному показателю водная среда\r\nслабощелочная. Загрязнений по флотореагентам не выявлено. Превышения ПДК \r\nнаблюдаются по компонентам: Ca, Mg, Feобщ, SO4 - в 1 цикле опробования, а \r\nтакже по SO4 во 2 цикле опробования.\r\n- 2П-03, техническое состояние скважины - удовлетворительное. \r\nСкважина расположена в 2 км на юг от русловой плотины. Водоносный горизонт \r\nвскрыт на границе четвертичных отложений и коренных пород, вскрыт в \r\nинтервале 12,0 – 19,5 м, уровень установился на глубине 3,5 м. \r\nВ 2025 году статический уровень подземных вод в скважине стабилен по \r\nгодам. В 1 и 2 цикле опробований основными анионами являются сульфаты (89-\r\n83%), в меньшей степени гидрокарбонаты, основными катионами служат кальций \r\n(75-59%) и в меньшей степени магний (20-34%). Воды нейтральные, сульфатные \r\nкальциевые в 1 цикле и сульфатные магниево-кальциевые во 2 цикле \r\nопробования. Минерализация по году составила 3,07 – 1,88 г/дм3\r\n, воды \r\nсолоноватые. Превышения ПДК наблюдаются по компонентам: Ca, Mg, SO4 - в 1 \r\nи 2 цикле опробования, а также по PO4\r\n3- в 1 цикле опробования. Загрязнений по \r\nфлотореагентам не выявлено.\r\n- 4П-1 (ПХ-4), техническое состояние скважины - удовлетворительное. \r\nСкважина расположена непосредственно у Водоподъемной дамбы №1. \r\nВодоносный горизонт вскрыт в выветрелой зоне коренных пород, на границе с \r\nчетвертичными породами. Статический уровень подземных вод в 2025 году \r\nстабильно находился на глубине 1,5 м. \r\nВ подотчетном году минерализация находится в пределах от 0,11 до 0,132\r\nг/дм3\r\n, воды ультрапресные. Тип вод в 1 и 2 полугодии сульфатно￾гидрокарбонатные магниево-кальциевые, слабощелочные, что указывает на \r\nводы подруслового талика р. Буровая. Превышения ПДК компонентам не \r\nнаблюдаются. Выявлено загрязнение по бутилксантогенату калия (Кх).\r\n- 4П-01, скважина расположена в нижнем бьефе Водоподъемной дамбы \r\n№1. Водоносный горизонт вскрыт в выветрелой зоне коренных пород, на границе \r\nс четвертичными породами, в интервале 6,0-23,0 м. По году статический уровень \r\nнаходился на уровне 4,0 - 5,0 м. \r\nПодземные воды ультрапресные, водная среда (pH) от нейтральной до \r\nслабощелочной. Тип вод сульфатно-гидрокарбонатные кальциево-магниевые\r\n(магниево-кальциевые), минерализация в пределах 0,056 – 0,132 г/дм3\r\n. \r\nХимический состав указывает на воды сезонно-талого слоя. Превышения ПДК \r\nкомпонентам не наблюдаются, за исключением повышенных показаний по \r\nаммонию (NH4\r\n+). Загрязнений по флотореагентам не выявлено.", "[стр. 31]\n31\r\n- 5П-1, скважина пробурена в 1999 г. в нижнем бьефе Водоподъемной \r\nдамбы №2. Водоносные горизонты вскрыты: в четвертичных породах в интервале \r\n0,0-7,6 м (обсажен) и в выветрелой зоне коренных пород, в интервале 7,6-40,0 \r\nм, статический уровень подземных вод находился на глубине - 11,3 м. В 2017 г.\r\nв скважине полностью прекратился приток, произведена чистка ствола от \r\nилистых отложений и выполнена прокачка/откачка. В 2025 гг. низкий\r\nстатический уровень на глубине 39,5 м указывает на небольшой подпор \r\nводоподъемной дамбы №2 со стороны ручья Безымянного и фильтрацию по \r\nоснованию дамбы. \r\nВ 2025 г. пробы подземные воды в 1 цикле (июнь) сульфатно￾гидрокарбонатные (хлоридные) кальциево-натриевые, воды пресные, \r\nслабощелочные (pH 8.2), с минерализацией 0,848 г/дм3\r\n. Превышения ПДК \r\nкомпонентам не наблюдаются, за исключением повышенных показаний по хлору \r\n(Cl), а также выявлено загрязнение по бутилксантогенату калия (Кх).\r\nВо 2 цикле опробования (сентябрь) состав отобранных вод указывал на \r\nподпитку водоносного горизонта за счет паводковых вод и вод атмосферных \r\nосадков, тип вод сульфатно-гидрокарбонатные магниево-кальциевые, \r\nультрапресные с минерализацией 0,244 г/дм3\r\n. Загрязнений подземных вод не \r\nвыявлено. По водородному показателю (pH) водная среда слабощелочная.\r\n- 5П-02, скважина пробурена в 2022 г. в нижнем бьефе Водоподъемной \r\nдамбы №2. Водоносные горизонты вскрыты: в четвертичных отложениях в \r\nинтервале 2,0-8,0 м (обсажен) и в коренных породах (выветрелая зона), в \r\nинтервале 24,0-39,0 м. \r\nВ 2025 г. статический уровень подземных вод на глубине 42 метра. Тип \r\nподземных вод в 1 цикле опробования - сульфатные кальциево-магниево￾натриевые, с минерализацией 0,69 г/дм3\r\n, во 2 цикле опробования сульфатно￾гидрокарбонатные магниево-кальциевые с минерализацией 0,4 г/дм3\r\n. По \r\nводородному показателю (pH) водная среда слабощелочная. Превышения ПДК \r\nпо компонентам: Feобщ, SO4, - в 1 и 2 цикле опробования, а также по PO4\r\n3- во 2 \r\nцикле опробования. Загрязнений по флотореагентам не выявлено.\r\n4.1.4. Результаты растеплений ледяных пробок в пьезометрических скважинах \r\nрежимной сети хвостохранилища НМЗ в 2025 году\r\nРезультаты растеплений ледяных пробок в скважинах и наблюдений за \r\nуровнем подземных вод в скважинах режимной гидрохимической сети\r\nхвостохранилища НМЗ в 2025 году приведены в таблице 4.7.\r\nТаблица 4.7. Результаты растеплений ледяных пробок и наблюдений за уровнем \r\nподземных вод в скважинах режимной сети хвостохранилища НМЗ в 2025 году", "[стр. 32]\n32", "[стр. 33]\n33\r\nРезультаты замеров статического уровня подземных вод за период \r\nнаблюдений с 2020 по 2025 гг. представлены в таблице 4.8., пьезометрические и \r\nгидрохимические скважины (наблюдательные) расположенные на низовом \r\nоткосе и в нижнем бьефе плотины, в районе старого русла р. Буровая – скв. 2П￾01 (ПХ-8) и далее ниже по течению р. Буровой – скважины 2П-02 (НХ-2) – в 1,2 \r\nкм от русловой плотины и скв. 2П-03 - в 2 км.\r\nВ отчетном году получены следующие результаты по уровням воды: в \r\nпьезометрах Русловой плотины после растепления ледяных пробок наблюдалось \r\nслабое обводнение грунтов основания в створах КИА №2 - №4 по скв. 2П-2 с \r\nмарта по август (уровень на глубине 32 м), в марте по скв. 3П-1 уровень на \r\nглубине 9,6 м, в марте по скв. 4П-1 уровень на глубине 8 м, с марта по август по \r\nскв. 4П-2 - уровень с 11 до 11,4 м, по скв. П-3-1 (7 м).\r\nВ ходе проведенных наблюдений за уровнем грунтовых вод по \r\nпьезометрическим скважинам с гребня Ограждающей дамбы получены \r\nследующие результаты: в створах КИА №1-3 растепление ледяных пробок \r\nуказывает на мерзлое состояние грунтов тела и до основания дамбы, а замер \r\nуровня после растепления льда и выстойки уровня через 24 часа не \r\nподтверждает притоки, таким образом подтвердить талое состояние грунтов \r\nвозможно только данными по термометрии. \r\nВ районе водоподъемной дамбы №2 обводнение грунтов наблюдалось с \r\nмарта по август месяц по скв. П-18, уровень находился на глубинах 25-27 м.", "[стр. 34]\n34\r\nТаблица 4.8. Статические уровни в пьезометрических и гидрохимических скважинах х/х НМЗ за 2020-2025 гг.", "[стр. 35]\n35\r\n4.1.5. Приведение в рабочее состояние скважин на хвостохранилища НМЗ\r\nВ 2025 году для Приведения в рабочее состояние скважин КИА от \r\nЗаказчика в марте выполнено задание по скважине Т-22н (потерна русловой \r\nплотины) и в октябре на скважине 2П-1 (ограждающая дамба).\r\nНа скв. Т-22н выполнено переоборудование по замеры уровня воды, \r\nустановка запорной арматуры и манометра, оборудование бетонного оголовка на \r\nустье и замена АКЗ. На скв. 2П-1 выполнена чистка скважины до забоя \r\nоборудование бетонного оголовка на устье.\r\n4.1.6. Обслуживание наружных элементов КИА\r\nРезультаты ремонтов КИА представлены в таблице 4.9.\r\nТаблица 4.9. Результаты Обслуживания скважин КИА на гидротехнических \r\nсооружениях хвостохранилища НМЗ в 2025 году\r\n4.1.7. Ликвидационный тампонаж скважин КИА на хвостохранилище НМЗ\r\nЛиквидационные работы в скважинах выполнялись в соответствии с \r\nПроектом производства работ (ППР) «Комплекс работ с применением буровой \r\nустановки по мониторингу состояния геологической среды на объектах ЗФ ПАО \r\n«ГМК «Норильский никель» в 2025 г.» и приняты заказчиком.", "[стр. 36]\n36\r\nПо заявке заказчика (НМЗ и ЦНГТС) на 2025 год, подрядной организацией \r\nООО НПО «Гидротехпроект» было выполнено ликвидационное тампонирование \r\nКИА на гидротехнических сооружениях хвостохранилища НМЗ:\r\n- 35 скважин в потерне русловой плотины хвостохранилища НМЗ; \r\n- 3 скважины на поверхности хвостохранилища НМЗ;\r\nВ 2025 году были ликвидированы скважины: \r\nПотерна русловой плотины хвостохранилища НМЗ:\r\n- ЗК-96 – ЗК-94 (март), всего 5 скважин;\r\n- ЗК-94 – ЗК-92 (май/июнь), всего 5 скважин;\r\n– ЗК-92 – ЗК-90 (сентябрь/октябрь), всего 10 скважин;\r\n- ЗК-90 – ЗК-88 – ЗК-84 (ноябрь/декабрь), всего 15 скважин.\r\n*«з/к» – замораживающая колонка*.\r\nРусловая плотина хвостохранилища НМЗ:\r\n- 3П-1, 4П-1 и 4П-2 (август).\r\nРаботы выполнены с соблюдением ОТ и ПБ и в соответствии со Стандартом \r\nорганизации «Гидрогеологические работы» СТО-03-03-2024.\r\nИсполнительная документация (Дела ликвидированных скважин) передана \r\nзаказчику.\r\n4.2 Мониторинг в пределах промышленной площадки НМЗ\r\n4.2.1 Результаты наблюдений за химическим составом подземных вод \r\nпромышленной площадки НМЗ\r\nЦелью данного мониторинга является наблюдение за изменением\r\nмерзлотно-гидрогеологических условий промышленной площадки НМЗ.\r\nДля рассматриваемого участка характерна четко выраженная тенденция к \r\nдеградации мерзлоты, что приводит к увеличению таликов, снижению \r\nпрочностных характеристик вечномерзлых грунтов при повышении их \r\nтемпературы, возможность образования сквозного талика. Вторым аспектом \r\nявляется взаимодействие техногенных подземных вод с элементами конструкции \r\nтехнологических коммуникаций и оценка устойчивости последних.\r\nГидрохимическая сеть объекта, создана в 2016-2020 годах, в 2024 году \r\nпробурены 2 скважины (ПР-7 и ПР-8) на восточном фланге г. Надежда, а также \r\nперебурена 1 скважина (ПР-1бис). В 2025 году дополнительно пробурена скв. ПР￾11. Режимная сеть на данный момент представлена скважинами: ПР-1бис, ПР-2, \r\nПР-3, ПР-4, ПР-5, ПР-6, ПР-7, ПР-8, ПР-9, ПР-10, ПР-11 (См. Рис. 1.2). \r\nСкважина ПР-4, восстановлена в 2022 году, находится в западной части \r\nпромышленной площадки НМЗ в 300 м на запад от плавильного цеха №1. \r\nВодоносный горизонт вскрыт в выветрелой зоне коренных пород, на границе с \r\nтехногенным грунтом, в интервале 6,0 – 10,0 м. По данным опробования\r\nскважины подземные воды сульфатные магниево- кальциевые, с минерализацией \r\n2,03 г/дм3\r\n.\r\nВ 2017 году пробурены скв. ПР-2 и ПР-3, которые по окончанию бурения \r\nбыли призваны безводными. После выстойки в течение 10-15 суток в скважинах \r\nбыли проведены термозамеры. Исходя из полученных данных верхняя граница \r\nзоны ММП, проходит на глубине 2,5 м, т.о. ниже данной глубины техногенное \r\nвоздействие от плавильного цеха не распространяется.", "[стр. 37]\n37\r\nВ сентябре 2017 года при проведении гидрохимического опробования в \r\nскважине ПР-3 было проведено растепление ледяной пробки от 2,5 м до забоя –\r\n80 м и откачка с дебитом, не превышающим 0,13 л/сек (0,47 м3\r\n/час). \r\nВ 2018 году пробурена скважина ПР-5, которая по окончанию бурения была \r\nпризнана безводной. После выстойки в течении 5 суток в скважине \r\nзафиксировано появление воды и отобрана проба, с 2019 года в скв. ПР-5 \r\nобводнение не проявлялось.\r\nВ 2020 году пробурена скважина ПР-6, которая по окончанию бурения была \r\nпризнана безводной и была оборудована под термометрические наблюдения.\r\nВ 2023 году скв. ПР-1 перебурена и под маркировкой ПР-1 бис была \r\nперенесена восточнее от плавильного цеха (в районе АБК ЦОСК), скважина\r\nоказалась безводна. Также восточнее и юго-восточнее от ПР-1бис были \r\nпробурены скважины ПР-7 (признана безводной) и ПР-8 (водоносный горизонт \r\nбыл вскрыт на глубине 17 м), скв. ПР-4 и ПР-8 были опробованы на сокращенный \r\nхимический анализ, при этом статический уровень в скв. ПР-8 находился на \r\nглубине 17 м, тип вод – гидрокарбонатно-сульфатные магниево-кальциевые, с \r\nминерализацией 3,23 г/дм3\r\n. По водородному потенциалу подземные воды –\r\nнейтральные, соответствуют водам подмерзлотного водоносного комплекса, \r\nвскрытого в коренных отложениях. По отношению к бетону и железобетону воды \r\nпо хлору относятся к неагрессивным и слабоагрессивным, по водородному \r\nпотенциалу относятся к неагрессивным, по отношению к сульфатам относятся к \r\nсильноагрессивным и неагрессивным, к металлоконструкциям –\r\nсреднеагрессивным.\r\nВ 2024 году пробурена скважина ПР-9 (глубина 60 м), расположена \r\nсевернее здания Кислородной станции (КС), а также южнее от КС пробурена\r\nскважина ПР-10 (глубина 60 м), по результатам бурения скважины признаны \r\nбезводными. В 2025 г. в скважинах водопроявлений не отмечено.\r\nВ 2025 году по результатам бурения скважины ПР-11 (глубина 120 м), \r\nрасположена в 50 м восточнее КПП «Станция Южная», водоносный горизонт \r\nподземных вод вскрыт не был (по геологическому разрезу - мерзлые породы), \r\nопробование не проводилось. \r\nРезультаты химического состава подземных вод из скважин \r\nнаблюдательной сети промплощадки НМЗ за 2025 год, а также за пятилетний \r\nпериод [3-7] приведены в таблице 4.10.\r\nФормулы Курлова и названия подземных вод из скважин наблюдательной \r\nсети промплощадки НМЗ за пятилетний период 2021-2025 гг. [3-7] приведены в \r\nтаблице 4.11.\r\nДанные по агрессивности подземных вод из скважин наблюдательной сети \r\nпромплощадки НМЗ за 2025 год, а также за пятилетний период [3-7] приведены \r\nв таблице 4.12.\r\nВ отчетном году подземные воды, отобранные из скв. ПР-4 в 2025 г., имеют \r\nтип - сульфатная кальциевая, с минерализацией 2,82 г/дм3\r\n., что превышает \r\nрезультаты 2024 года. Воды соответствуют водам подмерзлотного водоносного \r\nкомплекса, вскрытого в коренных отложениях. Режим наблюдений показал \r\nстатический уровень – 18,0 м. По отношению к бетону и железобетону воды по \r\nхлору относятся к неагрессивным, и слабоагрессивным, по водородному \r\nпотенциалу относятся к неагрессивным, по сульфатам к сильноагрессивным и \r\nслабоагрессивным, к металлоконструкциям - к среднеагрессивным.", "[стр. 38]\n38\r\nТаблица 4.10. Химический состав подземных вод на промышленной площадке НМЗ за 2020-2025 гг.\r\nТаблица 4.11. Формула Курлова и название подземных вод на промышленной площадке НМЗ за 2020-2025 гг.", "[стр. 39]\n39\r\nТаблица 4.12. Агрессивность подземных вод на промышленной площадке НМЗ за 2020-2025 гг.", "[стр. 40]\n40\r\nЗАКЛЮЧЕНИЕ\r\nРаботы по ведению мониторинга геологической среды на \r\nгидротехнических сооружениях Надеждинского металлургического завода имени \r\nБ.И. Колесникова ЗФ ПАО «ГМК «Норильский никель» в 2025 году выполнялись \r\nотделом мониторинга и гидрогеологического сопровождения проектов ООО «НН \r\nТехнические сервисы» в соответствии с дополнительным соглашением №1 \r\n№ННТС-ЗФ-2025/425-1ДС от 24.11.2025 к договору №НН-ТС-ЗФ-2025/425 от \r\n21.03.2025. Все права конфиденциальности соблюдены. \r\nПолевые работы с привлечением бурового и вспомогательного \r\nоборудования, а также составление данного отчета выполнялось подрядной \r\nорганизацией ООО НПО «Гидротехпроект» на основании дополнительного \r\nсоглашения №1 от 29.10.2025 №ННТС-409/2024-1ДС к договору № ННТС￾409/2024 от 28.01.2025. и в соответствии с Техническим заданием.\r\nНа производственной площадке НМЗ в отчетном году были пробурена\r\nскв. ПР-11 (120 п.м.), водоносный горизонт подземных вод не вскрыт. На \r\nскважину составлена полевая документация (паспорта), дела скважины\r\nпереданы Заказчику.\r\nВоды, отобранные из скв. ПР-4 в 2025 г. сульфатные кальциевые, с \r\nминерализацией 2,815 г/дм3\r\n. Воды соответствуют водам подмерзлотного \r\nводоносного комплекса, вскрытого в коренных отложениях. В наблюдательных \r\nскважинах ПР-1, ПР-2, ПР-3, ПР-5, ПР-6, ПР-7, ПР-9, ПР-10, ПР-11 также \r\nводопроявлений подземных вод не выявлено, скважины остаются безводными\r\n(«сухие»).\r\nПодземные воды, вскрытые при бурении скважины ПР-8 в 2023 г. относятся\r\nгидрокарбонатно-сульфатным магниево-кальциевым, с минерализацией 3,23\r\nг/дм3\r\n. Тип и состав соответствует подземным водам подмерзлотного водоносного \r\nкомплекса, вскрытого в коренных отложениях на глубине 17 м.\r\nНа хвостохранилище НМЗ в 2025 году при проведении наблюдений за \r\nуровнем воды в пьезометрических скважинах, расположенным на Ограждающей \r\nдамбе, появление техногенного водоносного горизонта не выявлено. В 1 створе \r\nКИА Ограждающей дамбы (верхний бьеф) в августе и ноябре текущего года \r\nзафиксированы водопроявления в пьезометрической скважине 1П-2 (на глуб. 18-\r\n19 м), а также в ноябре в пьезометрах 2П-2, 3П-2 (на глуб. 15 и 16 м), что \r\nвозможно только за счет инфильтрации поверхностных вод (в теплый период \r\nгода) от гребня дамбы к ее основанию. Присутствие ледяных пробок в отдельных \r\nскважинах – результат конденсата при перепаде температур у поверхности \r\nземли, возможно присутствие снега в стволах скважин при негерметичном \r\nзакрытии крышек на устье оголовка скважин, что приводит к появлению воды на \r\nзабое скважин в теплое время года и последующему замерзанию, т.к. тело и \r\nоснование дамбы - мерзлое. Пьезометры Ограждающей дамбы остаются сухими, \r\nчто подтверждается мерзлым состоянием грунтов тела и основания дамбы при\r\nрастеплении, а также по данным термометрии.\r\nВ пьезометрических скважинах, расположенных на гребне Русловой \r\nплотины (со стороны низового откоса) в створе КИА №1, №2 и№3 и №4 в случае \r\nводопроявлений на забое скважин или низкие уровни свидетельствуют о слабом\r\nподпоре со стороны пруда отстойника. В нижнем бьефе русловой плотины \r\nуровень подземных вод также находился на низких отметках, за исключением", "[стр. 41]\n41\r\nскважины 2П-01 где уровень стабильно находится на глубине 7 метров, что \r\nуказывает на гидродинамический подпор подземных вод таликовой части р. \r\nБуровой.\r\nНа водоподъемной дамбе №2 в скважине П-18 уровень находился на \r\nглубине 25-27 м, что в целом указывает на фильтрацию по основанию дамбы №2 \r\nв 2025 году.\r\nПо результатам наблюдений в гидрохимических наблюдательных \r\nскважинах: \r\n- 2П-01 (ПХ-8), в 2025 году уровенный режим в скважине практически не \r\nизменился и находился на глубине 7,0 м. Тип подземных вод сульфатные \r\nкальциево-магниевые, минерализация в пределах 7,38 – 6,93 г/дм3\r\n, воды \r\nсоленые. Превышения по предельно допустимым концентрациям (ПДК) \r\nнаблюдаются по компонентам: Ca, Mg, Feобщ, Na, SO4 - в 1 и 2 цикле опробования, \r\nа также по PO4\r\n3- в 1 цикле опробования. Спецкомпоненты не превышают пределы \r\nпогрешности. Величина водородного показателя варьирует на уровне прошлого \r\nгода, слабокислая среда pH от 6,0 до 6,6. \r\n- 2П-02 (НХ-2), в 2025 г. уровень воды в скважине установился на глубине \r\n0,9 м. Тип воды сульфатные магниево-кальциевые в 1 цикле опробования \r\nизменяются во 2 цикле на гидрокарбонатно-сульфатные магниево-кальциевые, \r\nминерализация по году в пределах 2,14 г/дм3 – 0,572 г/дм3\r\n, воды от солоноватых \r\nдо пресных. По водородному показателю водная среда слабощелочная. \r\nЗагрязнений по флотореагентам не выявлено. Превышения ПДК наблюдаются по \r\nкомпонентам: Ca, Mg, Feобщ, SO4, - в 1 цикле опробования, а также по SO4 во 2 \r\nцикле опробования.\r\n- 2П-03, статический уровень подземных вод в 2025 г.– 3,0 м и стабилен по \r\nгодам. Воды нейтральные, сульфатные кальциевые в 1 цикле и магниево￾кальциевые во 2 цикле опробования. Минерализация по году составила 3,07 –\r\n1,88 г/дм3\r\n, воды солоноватые. Превышения ПДК наблюдаются по компонентам: \r\nCa, Mg, SO4 - в 1 и 2 цикле опробования, а также по PO4\r\n3- в 1 цикле опробования. \r\nЗагрязнений по флотореагентам не выявлено.\r\n- 4П-1 (ПХ-4), в 2025 г. статический уровень подземных вод находился на \r\nглубине 1,5 м и стабилен по годам. Минерализация находится в пределах от 0,11 \r\nдо 0,132 г/дм3\r\n, воды ультрапресные. Тип вод сульфатно-гидрокарбонатные \r\nмагниево-кальциевые, слабощелочные. Превышения ПДК компонентам не \r\nнаблюдаются. Выявлено загрязнение по бутилксантогенату калия (Кх).\r\n- 4П-01, статический уровень находился на глубинах от 5,0 м, до 4,0 м от \r\nповерхности. Подземные воды ультрапресные, pH воды от нейтральной до \r\nслабощелочной. Тип вод сульфатно-гидрокарбонатные кальциево-магниевые \r\n(магниево-кальциевые), минерализация в пределах 0,056 – 0,132 г/дм3\r\n. \r\nПревышения ПДК компонентам не наблюдаются, за исключением повышенных \r\nпоказаний по аммонию (NH4+). Загрязнений по флотореагентам не выявлено.\r\n- 5П-1 в 2025 году наблюдения показали, что статический уровень на \r\nглубине 39,5 м. Подземные воды в 1 цикле (июнь) сульфатно-гидрокарбонатные \r\n(хлоридные) кальциево-натриевые, воды пресные, слабощелочные, с \r\nминерализацией 0,848 г/дм3\r\n. Превышения ПДК компонентам не наблюдаются, за \r\nисключением повышенных показаний по хлору (Cl), а также выявлено \r\nзагрязнение по бутилксантогенату калия (Кх). Во 2 цикле опробования (сентябрь) \r\nсостав отобранных вод указывает на подпитку водоносного горизонта за счет \r\nпаводковых вод и вод атмосферных осадков, тип вод сульфатно-", "[стр. 42]\n42\r\nгидрокарбонатные магниево-кальциевые, ультрапресные с минерализацией \r\n0,244 г/дм3\r\n. Загрязнений подземных вод не выявлено. \r\n- 5П-02, в 2025 г. статический уровень подземных вод на глубине 42 метра. \r\nТип подземных вод от сульфатных кальциево-магниево-натриевых, с \r\nминерализацией 0,69 г/дм3, до сульфатно-гидрокарбонатных магниево￾кальциевые с минерализацией 0,4 г/дм3\r\n. Водная среда слабощелочная. \r\nПревышения ПДК по компонентам: Feобщ, SO4, - в 1 и 2 цикле опробования, а \r\nтакже по PO4\r\n3 - во 2 цикле опробования. Загрязнений по флотореагентам не \r\nвыявлено.\r\nВ нижнем бьефе русловой плотины все фильтрующиеся подземные воды, \r\nа также воды сезонно-талого слоя в бортах долины р. Буровой перехватываются \r\nнасосной станцией возврата воды нижнего бьефа и перенаправляются в чашу \r\nхвостохранилища.\r\nРекомендуется продолжить наблюдения за химическим составом \r\nподземных вод гидрохимической наблюдательной сети хвостохранилища НМЗ, \r\nстатическими уровнями воды в пьезометрических скважинах, и наблюдательным \r\nгидрохимическим скважинам, расположенным на промышленной площадке НМЗ.", "[стр. 43]\n43\r\nСПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ\r\nНеопубликованная\r\n1. Программа (проект) мониторинга подземных вод в зоне эксплуатации \r\nподземного сооружения Надеждинского металлургического завода заполярного \r\nфилиала ОАО «ГМК «Норильский никель». Красноярск: МП ЭМР «ТЦ» \r\nЭвенкиягеомониторинг», 2015 г.\r\n2. Информационный отчет о проведенных работах по мониторингу состояния \r\nгеологической среды для Надеждинского металлургического завода в 2018 г. \r\nНорильск: ООО «Норильскгеология», 2018 г.\r\n3. Информационный отчет о проведенных работах по мониторингу состояния \r\nгеологической среды для Надеждинского металлургического завода в 2019 г. \r\nНорильск: ООО «Норильскгеология», 2019 г.\r\n4. Информационный отчет о проведенных работах по мониторингу состояния \r\nгеологической среды для Надеждинского металлургического завода в 2020 г. \r\nНорильск: ООО «Норильскгеология», 2020 г.\r\n5. Информационный отчет о проведенных работах по мониторингу состояния \r\nгеологической среды для Надеждинского металлургического завода в 2021 г. \r\nНорильск: ООО «Норникель Технические Сервисы», 2021 г.\r\n6. Информационный отчет о проведенных работах по мониторингу состояния \r\nгеологической среды для Надеждинского металлургического завода в 2022г. СПб: \r\nООО «Водный центр СПбГУ», 2022 г.\r\n7. Информационный отчет о проведенных работах по мониторингу состояния \r\nгеологической среды для Надеждинского металлургического завода в 2023 г. \r\nНорильск: ООО «Норникель Технические Сервисы», 2023 г.\r\n8. Информационный отчет о проведенных работах по мониторингу состояния \r\nгеологической среды для Надеждинского металлургического завода в 2024 г. \r\nНорильск: ООО «Норникель Технические Сервисы», 2024 г.", "[стр. 44]\n44\r\nПриложение 1\r\nАттестат аккредитации № RA.RU.21HH29", "[стр. 45]\n45\r\nПродолжение приложения 1", "[стр. 46]\n46\r\nПриложение 2\r\nПротоколы результатов химического анализа подземных вод из \r\nнаблюдательных скважин объектов НМЗ за 2025 г.", "[стр. 47]\n47\r\nПродолжение приложения 2", "[стр. 48]\n48\r\nПродолжение приложения 2", "[стр. 49]\n49\r\nПродолжение приложения 2", "[стр. 50]\n50\r\nПродолжение приложения 2", "[стр. 51]\n51\r\nПродолжение приложения 2", "[стр. 52]\n52\r\nПродолжение приложения 2", "[стр. 53]\n53\r\nПродолжение приложения 2", "[стр. 54]\n54\r\nПродолжение приложения 2", "[стр. 55]\n55\r\nПродолжение приложения 2", "[стр. 56]\n56\r\nПродолжение приложения 2", "[стр. 57]\n57\r\nПродолжение приложения 2", "[стр. 58]\n58\r\nПродолжение приложения 2", "[стр. 59]\n59\r\nПродолжение приложения 2", "[стр. 60]\n60\r\nПродолжение приложения 2", "[стр. 61]\n61\r\nПродолжение приложения 2"]};
